CREATE OR REPLACE FUNCTION public.tmp_siamois_person_for_name(p_raw text, p_last_name_first boolean,
                                                              p_institution_id bigint)
    RETURNS bigint
    LANGUAGE plpgsql AS
$fn$
DECLARE
    v_text      text := regexp_replace(trim(p_raw), '\s+', ' ', 'g');
    v_first     text;
    v_last      text;
    v_words     text[];
    v_capitals  text[] := '{}';
    v_others    text[] := '{}';
    v_word      text;
    v_person_id bigint;
    v_base      text;
    v_username  text;
    v_try       integer := 0;
BEGIN
    IF v_text ~ '[,&]' THEN
        v_last := trim(substring(v_text from '^([^,&]*)'));
        v_first := trim(substring(v_text from '^[^,&]*[,&](.*)$'));
    ELSE
        v_words := string_to_array(v_text, ' ');
        IF cardinality(v_words) = 1 THEN
            v_first := '';
            v_last := v_text;
        ELSE
            FOREACH v_word IN ARRAY v_words LOOP
                IF v_word ~ '[[:alpha:]]{2}' AND v_word = upper(v_word) THEN
                    v_capitals := v_capitals || v_word;
                ELSE
                    v_others := v_others || v_word;
                END IF;
            END LOOP;
            IF cardinality(v_capitals) > 0 AND cardinality(v_others) > 0 THEN
                v_last := array_to_string(v_capitals, ' ');
                v_first := array_to_string(v_others, ' ');
            ELSIF p_last_name_first THEN
                v_last := v_words[1];
                v_first := array_to_string(v_words[2:], ' ');
            ELSE
                v_first := v_words[1];
                v_last := array_to_string(v_words[2:], ' ');
            END IF;
        END IF;
    END IF;
    v_first := left(coalesce(v_first, ''), 64);
    v_last := left(coalesce(v_last, ''), 64);

    SELECT p.person_id
    INTO v_person_id
    FROM public.person p
    WHERE lower(public.unaccent(trim(coalesce(p.name, '')))) = lower(public.unaccent(v_first))
      AND lower(public.unaccent(trim(coalesce(p.lastname, '')))) = lower(public.unaccent(v_last))
      AND EXISTS (SELECT 1
                  FROM public.person_profile_assignment ppa
                           JOIN public.profile pr ON pr.profile_id = ppa.fk_profile_id
                  WHERE ppa.fk_person_id = p.person_id
                    AND pr.fk_institution_id = p_institution_id)
    ORDER BY p.person_id
    LIMIT 1;
    IF v_person_id IS NOT NULL THEN
        RETURN v_person_id;
    END IF;

    v_base := regexp_replace(lower(public.unaccent(v_first || '.' || v_last)), '[^a-z0-9.]', '', 'g');
    v_base := regexp_replace(regexp_replace(v_base, '\.{2,}', '.', 'g'), '^\.+|\.+$', '', 'g');
    IF v_base = '' THEN
        v_base := 'user';
    END IF;
    v_base := left(v_base, 27);
    v_username := v_base;
    WHILE EXISTS (SELECT 1 FROM public.person WHERE username = v_username) LOOP
        v_try := v_try + 1;
        v_username := v_base || v_try;
    END LOOP;

    INSERT INTO public.person (name, lastname, username, password, is_enabled)
    VALUES (v_first, v_last, v_username, md5(random()::text || clock_timestamp()::text), false)
    RETURNING person_id INTO v_person_id;
    INSERT INTO public.pending_person (fk_person_id) VALUES (v_person_id);
    RETURN v_person_id;
END;
$fn$;

CREATE OR REPLACE FUNCTION public.tmp_siamois_add_awaiting_member(p_person_id bigint, p_institution_id bigint,
                                                                  p_project_id bigint)
    RETURNS void
    LANGUAGE sql AS
$fn$
INSERT INTO public.person_profile_assignment (fk_person_id, fk_profile_id)
SELECT p_person_id, pr.profile_id
FROM public.profile pr
WHERE ((pr.code = 'ORGANIZATION_MEMBER' AND pr.fk_institution_id = p_institution_id AND pr.fk_action_unit_id IS NULL)
    OR (pr.code = 'PROJECT_MEMBER' AND pr.fk_action_unit_id = p_project_id))
  AND EXISTS (SELECT 1
              FROM public.pending_person pp
              WHERE pp.fk_person_id = p_person_id
                AND pp.register_token IS NULL)
ON CONFLICT DO NOTHING;
$fn$;
